 INSERT INTO tr_balancesheet(
bal_id, shift_id, advance_credit, date_of_transaction, last_modified, status,  mode_c_q, shift_userid, adv_receipt_id, gh_id, block_id)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ? );


UPDATE public.vehicle_allotment SET req_id=?, vehicle_details=?, vehicle_no=?, driver_name=?, driver_mobileno=?, time_of_report=?, 
place_of_report=?, status=?, gh_id=?, vehicle_start_time=?, vehicle_end_time=?, block_id=?, protocol_name=?, protocol_mobileno=?
WHERE vehicle_reqid=? and trip_status=?;


INSERT INTO tr_conf_bill(
conf_bill_id,req_id, charge, status, entrydate, gh_id,additionalcharge,advance_amount,mode_of_payment)
VALUES (?, ?, ?, ?, now(), ?,?,?,?);


		INSERT INTO tr_conf_receipt(
		conf_receipt_id, conf_bill_id, payed, status, entrydate, gh_id, balance, conf_req_id)
		VALUES (?, ?, ?, ?, now(), ?, ?, ?);

		
INSERT INTO partial_cancel_request(
pcr_id, from_date, to_date, req_id, status, last_modified)
VALUES (?, ?, ?, ?, ?, now());

		
SELECT COALESCE(extra_guest, 0) AS extra_guest 
FROM gad_request 
WHERE req_id = ?;

			
	INSERT INTO adminr.user_password_history(
	user_id, password, role, lastupdated_by, perform_on, lastupdated_on)
	VALUES (?, ?, ?, ?, ?, NOW());


	INSERT INTO tr_conf_receipt(
	conf_receipt_id, conf_bill_id, payed, status, entrydate, gh_id, balance, conf_req_id)
	VALUES (?, ?, ?, ?, now(), ?, ?, ?);
